SELECT method, CASE WHEN amount >= 1420 THEN 'high' WHEN amount >= 790 THEN 'mid' ELSE 'low' END AS amount_bucket, SUM(CASE WHEN method = 'bank_transfer' THEN 1 ELSE 0 END) AS bank_transfer_count, ROUND(AVG(amount), 2) AS avg_amount FROM payments GROUP BY method, CASE WHEN amount >= 1420 THEN 'high' WHEN amount >= 790 THEN 'mid' ELSE 'low' END HAVING SUM(CASE WHEN method = 'bank_transfer' THEN 1 ELSE 0 END) < 59
